import { Group } from '@visx/group';
import React, { PropsWithChildren } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { useOrientation } from '../context/RangeLegendOrientationContext.js';
import { getSegmentItemPositionAndSize } from '../functions/get-segment-item-position-and-size.js';
import {
  DEFAULT_ITEM_THICKNESS,
  DEFAULT_GAP_THICKNESS,
  DEFAULT_COLOR,
} from '../types/default.js';

interface RangeLegendSegmentsItemProps {
  size: number;
  startPosition: number;
  color?: string;
  showGap: boolean;
}

export const RangeLegendSegmentsItem = (
  props: PropsWithChildren<RangeLegendSegmentsItemProps>,
) => {
  const { size, startPosition, color, showGap, children } = props;
  const { orientation } = useOrientation();

  const { itemHeight, itemWidth, itemX, itemY } = getSegmentItemPositionAndSize(
    orientation,
    startPosition,
    size,
  );

  const horizontalGap = `0, ${itemWidth}, ${DEFAULT_ITEM_THICKNESS}, ${
    itemWidth + DEFAULT_ITEM_THICKNESS
  }`;
  const verticalGap = `0, ${
    DEFAULT_ITEM_THICKNESS + itemHeight
  }, ${DEFAULT_ITEM_THICKNESS}, ${itemHeight}`;

  return (
    <Group>
      <rect
        x={itemX}
        y={itemY}
        width={itemWidth}
        height={itemHeight}
        fill={color ?? DEFAULT_COLOR}
        stroke={showGap ? 'none' : Colors.Background.Base.Default}
        strokeWidth={DEFAULT_GAP_THICKNESS}
        strokeDasharray={
          orientation === 'horizontal' ? horizontalGap : verticalGap
        }
      ></rect>
      {children}
    </Group>
  );
};

RangeLegendSegmentsItem['displayName'] = 'RangeLegendSegmentsItem';
